package com.atharok.btremote.automation

object WebConsole {
val html = """<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AiPhoneKVM</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#172534;font:16px/1.6 system-ui,sans-serif}main{max-width:900px;margin:auto;padding:24px}h1{margin:0}h2{font-size:20px}section{background:white;border:1px solid #dce3eb;border-radius:16px;padding:20px;margin:16px 0}input,textarea,button{font:inherit;border:1px solid #aebccb;border-radius:9px;padding:10px;max-width:100%}input,textarea{width:100%;margin:5px 0 12px}button{background:#176552;color:white;cursor:pointer;margin:4px}button.secondary{background:white;color:#174f43}.row{display:flex;gap:12px}.row>*{flex:1}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf1f5;padding:14px;border-radius:10px}#frame{max-width:100%;max-height:650px}small{color:#516071}label{display:block}#notice{color:#a02b20}
</style><main><h1>AiPhoneKVM</h1><p>电脑 → 主控端 → 蓝牙 → 被控端</p>
<section><label>控制令牌（从主控端复制）<input id="token" type="password" autocomplete="off"></label><button id="connect">连接 / 刷新状态</button><pre id="status">尚未连接</pre><small>令牌仅保留在当前页面内存。仅在可信局域网或 VPN 使用。</small></section>
<section><h2>目标自动执行</h2><label>任务目标<textarea id="goal" rows="3" placeholder="描述希望被控端完成的事情"></textarea></label><div class="row"><label>最多操作步数<input id="maxSteps" type="number" min="1" max="120" value="30"></label><label>最长运行分钟<input id="maxMinutes" type="number" min="1" max="60" value="15"></label></div><button id="startTask">开始自动执行</button><button id="stopTask" class="secondary" disabled>停止任务</button><pre id="taskState">尚未开始</pre><small>自动循环截图、识别和操作，用新截图确认完成。离开主控端AI工作区会停止任务；关闭本网页不会停止手机上的任务。</small></section>
<section><h2>执行命令</h2><textarea id="command" rows="5">{"action":"STATUS","params":{}}</textarea><button id="send">执行</button><button id="cancel" class="secondary">停止并松键</button><pre id="result">支持 TAP / SWIPE / INPUT / KEY_PRESS / KEY_COMBO / CALIBRATE 等 BlueHIDFlow 命令。</pre></section>
<section><h2>被控端截图</h2><p>先在被控端截图助手中填写主控端地址和截图配对码，并确认屏幕共享。</p><button id="capture">请求被控端截图</button><p id="frameInfo"></p><img id="frame" alt="被控端的屏幕截图"></section>
<section><h2>备用坐标与 MQTT 设置</h2><small>新版被控端助手自动上报设备、尺寸和方向，可在状态中查看 enhancedControl.screen；以下尺寸只在没有自动屏幕信息时使用。</small><div class="row"><label>备用宽度<input id="width" type="number"></label><label>备用高度<input id="height" type="number"></label><label>像素/HID单位<input id="sens" type="number" step="0.01"></label></div><label>MQTT 地址<input id="uri" placeholder="ssl://主机:8883"></label><label>用户名<input id="username" autocomplete="off"></label><label>密码（留空保持原值）<input id="password" type="password" autocomplete="new-password"></label><label>主题前缀<input id="prefix"></label><label>自定义 CA PEM（留空保持原值）<textarea id="ca" rows="3"></textarea></label><button id="save">保存配置</button><small>修改 HTTP 端口或清空密码/证书，请在主控端上停止服务后操作。</small></section>
<section><h2>最近记录</h2><button id="logs" class="secondary">刷新记录</button><pre id="logText"></pre></section><p id="notice" role="status"></p><small>报告发送成功不代表已确认目标界面变化。助手上报屏幕尺寸优先；增强触屏无需鼠标校准，纯蓝牙鼠标仍需校准。基于 GPL-3.0 的 PhoneKVM / BtRemote，协议参考 Apache-2.0 的 BlueHIDFlow。</small></main>
<script>
const el=id=>document.getElementById(id);let imageUrl,taskTimer;
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+el('token').value,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw Error((await r.text()).slice(0,250));return r.headers.get('content-type').includes('image/')?await r.blob():await r.json()}
function run(fn){return async()=>{el('notice').textContent='';try{await fn()}catch(e){el('notice').textContent=e.message}}}
function showTask(s){el('taskState').textContent=s.label+' · 已操作 '+s.steps+' 步 · 已识别 '+s.rounds+' 轮\n'+s.summary+'\n'+s.message;for(const id of ['startTask','goal','maxSteps','maxMinutes','send','save','capture'])el(id).disabled=s.active;el('stopTask').disabled=!s.active}
async function watchTask(){clearTimeout(taskTimer);const s=await api('/api/ai/task');showTask(s);if(s.active)taskTimer=setTimeout(run(watchTask),1000)}
el('startTask').onclick=run(async()=>{await api('/api/ai/task',{goal:el('goal').value,maxSteps:Number(el('maxSteps').value),maxMinutes:Number(el('maxMinutes').value)});await watchTask()});
el('stopTask').onclick=run(async()=>{showTask(await api('/api/ai/task/stop',{}));clearTimeout(taskTimer)});
el('connect').onclick=run(async()=>{el('status').textContent=JSON.stringify(await api('/api/status'),null,2);const c=await api('/api/config');el('width').value=c.phone.screenWidth;el('height').value=c.phone.screenHeight;el('sens').value=c.phone.hidSensitivity;el('uri').value=c.mqtt.uri;el('username').value=c.mqtt.username;el('prefix').value=c.mqtt.topicPrefix;await watchTask()});
el('send').onclick=run(async()=>{const c=JSON.parse(el('command').value);c.id=c.id||c.message_id||('web-'+Date.now()+'-'+Math.random());el('result').textContent=JSON.stringify(await api('/api/command',c),null,2)});
el('cancel').onclick=run(async()=>{el('result').textContent=JSON.stringify(await api('/api/command',{action:'CANCEL'}),null,2)});
el('save').onclick=run(async()=>{const mqtt={uri:el('uri').value,username:el('username').value,topicPrefix:el('prefix').value};if(el('password').value)mqtt.password=el('password').value;if(el('ca').value)mqtt.caCert=el('ca').value;const c=await api('/api/config',{phone:{screenWidth:Number(el('width').value),screenHeight:Number(el('height').value),hidSensitivity:Number(el('sens').value)},mqtt});el('notice').textContent='配置已保存';el('password').value='';});
el('logs').onclick=run(async()=>{el('logText').textContent=(await api('/api/logs')).logs.join('\n')});
el('capture').onclick=run(async()=>{el('frameInfo').textContent='等待被控端截图…';const c=await api('/api/capture',{});const blob=await api('/api/capture/latest');if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=URL.createObjectURL(blob);el('frame').src=imageUrl;el('frameInfo').textContent=c.width+' × '+c.height+' · '+new Date(c.captured_at).toLocaleString()});
</script></html>"""
}
